-- Semilla de dev y staging: la clasificación de cada competición de standings.csv
-- (docs/04-datos/datos-ejemplo/). No se edita a mano: la escribe scripts/datos-ejemplo/semillas.mjs.
-- Es repetible e idempotente: INSERT IGNORE sobre la clave única competición + equipo.
INSERT IGNORE INTO standings (competition_id, team_id, points, played, won, lost, sets_won, sets_lost, penalty_points, created_at, updated_at)
  SELECT c.id, (SELECT id FROM teams WHERE season_id = (SELECT id FROM seasons WHERE name = '2026-27') AND category_id = (SELECT id FROM categories WHERE name = 'Alevín' AND gender = 'MALE') AND name = 'Roque Vóley'), 13, 6, 5, 1, 16, 7, 0, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6) FROM competitions c WHERE c.season_id = (SELECT id FROM seasons WHERE name = '2026-27') AND c.category_id = (SELECT id FROM categories WHERE name = 'Alevín' AND gender = 'MALE') AND c.name = 'Liga Insular Alevín masculina';
